// fleetDirectorBridge (#architect-creates-a-director-with-discovery) — decide what a
// `bsc fleet director new` request does to the store.
//
// Pure on purpose: the DECISION is testable without Tauri or a rendered app, and the listener stays a
// thin adapter — the same split `fleetWakeBridge` and `systemSessionBridge` use.
//
// WHY IT BUILDS A FleetPlan INSTEAD OF PLACING A PANE ITSELF
// A director is not just a pane: it is a cwd at the project hub, a `director-kickoff.md` startup doc,
// a checkpoint doc, a `director` role, a director DRIVE and a director MODE, on a pane id the rest of
// the app already knows how to find. All of that lives in `fleetStartProject`, which is exercised by
// every real fleet launch. Reimplementing the subset here would be a second launch path that drifts
// from the first — the "superseded but never removed" duplication this codebase has paid for more
// than once. So this constructs the SMALLEST honest FleetPlan (a director, no streams) and hands it
// to the path that already works.
//
// The plan is a launch input, not a stored one: nothing here writes plan.db, so a project whose real
// fleet has ten streams keeps them. Launching the full fleet later rebuilds the tab in place.
//
// WHY THE KICKOFF IS SEEDED AS TEXT, BEFORE THE PANES EXIST (#the-director-launches-with-no-kickoff-prompt)
// `fleetStartProject` seeds the director's kickoff as a DOC PATH (`paneStartupPromptDocs`), which
// TerminalView resolves once, inside its launch effect, with a `read_document` round trip. That is the
// route whose failure mode is already documented on the `startupPrompt` prop: "the store value is read
// ONCE… so any surface that writes it after this runs loses it silently — which is how every debug
// session came up as a bare `claude` with nothing to do". Debug and studio sessions were migrated off
// it; the director never was, and it launches with a STABLE pane id into a hub directory where other
// sessions have already run.
//
// So the caller resolves the kickoff to TEXT and seeds it here, BEFORE `fleetStartProject` creates any
// pane. Two things follow, and both are the point: `paneStartupPromptText` is what TerminalView
// prefers, so no `read_document` runs at launch and a failed read can no longer degrade the director
// to the generic project-init prompt; and the value is in the store before the pane it keys exists, so
// the one-shot read cannot be racing a write that has not happened.
//
// This is NOT an injection path and `injectCallers.test.ts` stays green on its empty set: the text is
// baked into the launch as claude's initial-message argument, exactly as the doc route did. Nothing is
// typed into a running session.

// The deep type path, matching `AppBanners` (the other shell-side fleet launcher): a cross-feature
// `import type` is allowed, and `FleetPlan` is not on the planner barrel.
import type { FleetPlan } from "@/features/planner/fleet/planFleet";

/** The request as it arrives from Rust (`bsc://fleet-director`). */
export interface DirectorRequest {
  /** Correlates the ack. */
  id: string;
  projectKey: string;
  /** `<projectKey>:director` — resolved in Rust so create/list/brief share one spelling. */
  paneId: string;
  /** The absolute hub path, resolved in Rust (#905) so the launch never depends on the
   *  async-loaded `bscBaseDir` mirror — an empty one drops the session at the user root. */
  hubPath: string;
}

/** What we send back via `fleet_director_ack`. */
export interface DirectorAck {
  id: string;
  error?: string;
  created: boolean;
}

/**
 * The store surface this needs — narrowed so the pure fn stays decoupled from the slice.
 */
export interface DirectorDeps {
  /** The real `fleetStartProject`. */
  fleetStartProject: (
    projectName: string,
    fleet: FleetPlan,
    projectKey: string,
    paths?: { hubPath?: string; worktreePaths?: Record<string, string> },
    // `string[]`, not `unknown`. The real action returns ONE ROSTER ROW PER LIVE SESSION, and that is
    // the only evidence a pane exists — typing it `unknown` erased the evidence and made ignoring it
    // invisible to tsc, which is how this ack came to report a success it had never checked.
  ) => string[];
  /** Seed `paneStartupPromptText` for one pane. Called BEFORE the launch — see the header. */
  seedStartupPromptText?: (paneId: string, text: string) => void;
}

/**
 * The smallest honest fleet: a director and nothing else.
 *
 * `recommended: 0` and an empty `streams` are the TRUTH here, not placeholders — this launch is not a
 * fleet, and claiming a worker count would put a number on the tab that no session backs. `reasoning`
 * is carried because it is what a later reader sees when asking why this tab has one pane.
 */
export function directorOnlyPlan(): FleetPlan {
  return {
    recommended: 0,
    reasoning:
      "Director created on its own by the architect (bsc fleet director new) — no worker streams were planned with it.",
    streams: [],
    director: { enabled: true },
  };
}

/**
 * Apply a `bsc fleet director new` request.
 *
 * Rust has already settled everything checkable before this runs: the project exists, no director is
 * live, and the kickoff is on disk. What is left is the launch.
 *
 * `kickoffText` is the resolved contents of `prompts/director-kickoff.md`. When present it is seeded
 * BEFORE the launch, so the pane it keys does not exist yet and the one-shot read in TerminalView
 * cannot miss it. When absent — an unreadable doc, or a caller that did not resolve one — the launch
 * still proceeds and `fleetStartProject`'s doc route remains the fallback, because a director with the
 * old delivery is strictly better than no director.
 */
export function applyDirectorNew(req: DirectorRequest, deps: DirectorDeps, kickoffText?: string): DirectorAck {
  const { id } = req;
  const projectKey = (req.projectKey ?? "").trim();
  if (!projectKey) return { id, error: "fleet director: no project key", created: false };

  try {
    const text = (kickoffText ?? "").trim();
    // ORDER IS THE FIX. Seeding after `fleetStartProject` would write into a pane that may already
    // have mounted, launched, and read — which is the race this exists to remove, not to relocate.
    if (text && req.paneId && deps.seedStartupPromptText) {
      deps.seedStartupPromptText(req.paneId, text);
    }
    // The project's own key doubles as its display name here. `fleetStartProject` uses the first
    // argument only to NAME the tab (`<name> · build`), and the key is what the architect asked for —
    // a prettier title would have to come from a store read this pure function deliberately avoids.
    // THE RETURN VALUE IS THE ONLY EVIDENCE A PANE EXISTS, and ignoring it made this ack a lie.
    //
    // MEASURED 2026-09-04 on village-animal-hospital: `bsc fleet director new` printed "created the
    // director", and the count of `/bin/bash` panes under the app stayed at 1 for twelve seconds
    // afterwards. No pane, no `fleet.roster.tsv` in the hub, and the project absent from
    // `bsc fleet directors` — while the caller had been told it worked.
    //
    // `fleetStartProject` returns ONE ROSTER ROW PER LIVE SESSION (`<paneId>\t…`), so an empty
    // result means it launched nothing. The old code caught only a THROW, which a store action that
    // simply declines never performs — so every silent decline reported success.
    //
    // Rust already refuses a false ack (`if !ack.created { return Err(…) }`); it just had nothing
    // truthful to refuse on. This gives it that.
    const rows = deps.fleetStartProject(projectKey, directorOnlyPlan(), projectKey, { hubPath: req.hubPath || undefined }) ?? [];
    const launched = rows.some((r) => r.startsWith(`${req.paneId}\t`));
    if (!launched) {
      return {
        id,
        created: false,
        error:
          `fleet director: the launch produced no session for '${req.paneId}' ` +
          `(fleetStartProject returned ${rows.length} roster row(s)). The kickoff is on disk, so the ` +
          `project looks seeded — it has no director behind it.`,
      };
    }
    return { id, created: true };
  } catch (err) {
    return {
      id,
      error: `fleet director: the launch threw: ${err instanceof Error ? err.message : String(err)}`,
      created: false,
    };
  }
}

