import { describe, it, expect, vi } from "vitest";
import { applyDirectorNew, directorOnlyPlan, type DirectorRequest, type DirectorDeps } from "@/app/fleetDirectorBridge";

function req(over: Partial<DirectorRequest> = {}): DirectorRequest {
  return {
    id: "r1",
    projectKey: "studio-code",
    paneId: "studio-code:director",
    hubPath: "C:/hub/studio-code",
    ...over,
  };
}

/** A roster row exactly as `fleetStartProject` emits one for a director: `<paneId>\tdirector\t-\t-\tdirector`. */
export const directorRow = (paneId: string) => `${paneId}\tdirector\t-\t-\tdirector`;

// THE DEFAULT MOCK NOW LAUNCHES SOMETHING, and that change is the point rather than housekeeping.
// It used to be a bare `vi.fn()` returning undefined — a launch that produced NO session — and every
// test here asserted `created: true` against it. So the suite encoded the bug it should have caught:
// `bsc fleet director new` reported success for a director that did not exist, and these tests agreed.
function deps(over: Partial<DirectorDeps> = {}): DirectorDeps & { fleetStartProject: ReturnType<typeof vi.fn> } {
  // DERIVES the pane id from the projectKey it is called with, exactly as the real action does
  // (`<projectKey>:director`). A hardcoded id would pass only for whichever project the first test
  // happened to use, and would then fail the others for the wrong reason.
  return {
    fleetStartProject: vi.fn((_name: string, _plan: unknown, key: string) => [directorRow(`${key}:director`)]),
    ...over,
  } as never;
}

describe("directorOnlyPlan", () => {
  it("enables the director and launches NO worker streams", () => {
    const plan = directorOnlyPlan();
    expect(plan.director.enabled).toBe(true);
    expect(plan.streams).toEqual([]);
  });

  it("claims zero recommended workers rather than a number nothing backs", () => {
    // `recommended` drives what the UI says the fleet SHOULD be running. A create that launched one
    // pane while claiming a worker count would read as a fleet that had mostly failed to start.
    expect(directorOnlyPlan().recommended).toBe(0);
  });

  it("carries a reasoning that explains the single pane", () => {
    // It is what a later reader sees when asking why this build tab has one session in it.
    expect(directorOnlyPlan().reasoning).toMatch(/architect/i);
    expect(directorOnlyPlan().reasoning).toMatch(/no worker streams/i);
  });
});

describe("applyDirectorNew", () => {
  it("launches through fleetStartProject with the project key and the resolved hub path", () => {
    const d = deps();
    const ack = applyDirectorNew(req(), d);

    expect(ack).toEqual({ id: "r1", created: true });
    expect(d.fleetStartProject).toHaveBeenCalledTimes(1);
    const [name, plan, key, paths] = d.fleetStartProject.mock.calls[0];
    expect(name).toBe("studio-code");
    expect(key).toBe("studio-code");
    expect(plan.director.enabled).toBe(true);
    expect(plan.streams).toEqual([]);
    // The ABSOLUTE hub path from Rust (#905) — without it the launch falls back to the async
    // `bscBaseDir` mirror, which is empty at startup and drops the session at the user root.
    expect(paths).toEqual({ hubPath: "C:/hub/studio-code" });
  });

  it("passes hubPath as undefined rather than an empty string when Rust could not resolve one", () => {
    // `fleetStartProject` treats a falsy hubPath as "fall back to the mirror"; an empty STRING would
    // be a path it tries to use.
    const d = deps();
    applyDirectorNew(req({ hubPath: "" }), d);
    expect(d.fleetStartProject.mock.calls[0][3]).toEqual({ hubPath: undefined });
  });

  it("refuses an empty project key without launching anything", () => {
    const d = deps();
    for (const projectKey of ["", "   "]) {
      const ack = applyDirectorNew(req({ projectKey }), d);
      expect(ack.created).toBe(false);
      expect(ack.error).toBeTruthy();
    }
    expect(d.fleetStartProject).not.toHaveBeenCalled();
  });

  it("reports a throwing launch as a stated error rather than propagating it", () => {
    // A throw would strand the Rust waiter until its timeout and surface as "the frontend did not
    // create the director", sending someone to debug the wrong layer.
    const d = deps({ fleetStartProject: vi.fn(() => { throw new Error("no tab"); }) } as never);
    const ack = applyDirectorNew(req(), d);
    expect(ack.created).toBe(false);
    expect(ack.error).toContain("no tab");
  });

  it("always echoes the request id back, so the Rust waiter is never stranded", () => {
    const d = deps({ fleetStartProject: vi.fn(() => { throw new Error("x"); }) } as never);
    expect(applyDirectorNew(req({ id: "corr-9" }), d).id).toBe("corr-9");
    expect(applyDirectorNew(req({ id: "corr-9", projectKey: "" }), deps()).id).toBe("corr-9");
  });

  it("never reports created:true on a path that did not launch", () => {
    // The one invariant the ack carries: the kickoff is already on disk by the time this runs, so a
    // false success leaves a project looking seeded with no session behind it.
    const failing = deps({ fleetStartProject: vi.fn(() => { throw new Error("x"); }) } as never);
    expect(applyDirectorNew(req(), failing).created).toBe(false);
    expect(applyDirectorNew(req({ projectKey: "" }), deps()).created).toBe(false);
  });
});

// ── The kickoff must reach the launch (#the-director-launches-with-no-kickoff-prompt) ──
//
// The director launched and then sat at an empty prompt: a hub with a correct
// `prompts/director-kickoff.md` produced a claude session directory and ZERO transcripts. The store
// half was never the problem — `launchPromptDelivery.test.ts` already proves `fleetStartProject` seeds
// `paneStartupPromptDocs[<key>:director]`. What was missing is the half debug and studio sessions were
// migrated to and the director never was: hand the resolved TEXT down before the pane exists, so the
// one-shot read inside TerminalView's launch effect cannot miss it.

describe("applyDirectorNew — kickoff delivery", () => {
  it("seeds the kickoff TEXT BEFORE the launch, so no pane exists to miss it", () => {
    const order: string[] = [];
    const d = {
      fleetStartProject: vi.fn(() => { order.push("launch"); }),
      seedStartupPromptText: vi.fn(() => { order.push("seed"); }),
    } as never as DirectorDeps;

    applyDirectorNew(req({ paneId: "proj-key:director" }), d, "read what the architect settled");

    // ORDER IS THE ASSERTION. Seeding after the launch would write into a pane that may already have
    // mounted and read — relocating the race rather than removing it.
    expect(order).toEqual(["seed", "launch"]);
    expect((d as unknown as { seedStartupPromptText: ReturnType<typeof vi.fn> }).seedStartupPromptText)
      .toHaveBeenCalledWith("proj-key:director", "read what the architect settled");
  });

  it("still launches when the kickoff could not be resolved — the doc route stays the fallback", () => {
    const seed = vi.fn();
    const start = vi.fn((_n: string, _p: unknown, key: string) => [directorRow(`${key}:director`)]);
    const ack = applyDirectorNew(req(), { fleetStartProject: start, seedStartupPromptText: seed } as never, undefined);
    expect(ack.created).toBe(true);
    expect(start).toHaveBeenCalled();
    // A director delivered the old way beats no director at all.
    expect(seed).not.toHaveBeenCalled();
  });

  it("treats a blank kickoff as unresolved rather than seeding emptiness", () => {
    const seed = vi.fn();
    applyDirectorNew(req(), { fleetStartProject: vi.fn(), seedStartupPromptText: seed } as never, "   \n  ");
    // Seeding "" would satisfy TerminalView's `text !== undefined` check and deliver NOTHING, which is
    // worse than falling through to the doc.
    expect(seed).not.toHaveBeenCalled();
  });

  it("works when the caller supplies no seeder at all", () => {
    // The pure fn must not require the dep — an older caller is a launch that still happens.
    const ack = applyDirectorNew(
      req(),
      { fleetStartProject: vi.fn((_n: string, _p: unknown, key: string) => [directorRow(`${key}:director`)]) } as never,
      "text",
    );
    expect(ack.created).toBe(true);
  });
});


describe("the ack reports what actually launched (a-director-pane-comes-up-without-its-agent)", () => {
  it("refuses when the launch produced no session", () => {
    // MEASURED on village-animal-hospital: `bsc fleet director new` printed "created the director"
    // while the count of bash panes under the app stayed flat for twelve seconds. The old code caught
    // only a THROW, which a store action that simply declines never performs.
    const d = deps({ fleetStartProject: vi.fn(() => []) });
    const ack = applyDirectorNew({ id: "1", projectKey: "proj", paneId: "proj:director", hubPath: "/h" }, d);
    expect(ack.created).toBe(false);
    expect(ack.error).toContain("proj:director");
    expect(ack.error).toContain("no session");
  });

  it("refuses when it launched SOMETHING but not this director", () => {
    // A roster with rows in it is not proof the DIRECTOR is among them — counting rows would pass
    // here, which is why the check matches the pane id.
    const d = deps({ fleetStartProject: vi.fn(() => ["proj:worker-a\tstream\tr\tb\tworker"]) });
    const ack = applyDirectorNew({ id: "1", projectKey: "proj", paneId: "proj:director", hubPath: "/h" }, d);
    expect(ack.created).toBe(false);
  });

  it("says the kickoff is on disk, so the operator is not left hunting for a half-seeded project", () => {
    const d = deps({ fleetStartProject: vi.fn(() => []) });
    const ack = applyDirectorNew({ id: "1", projectKey: "proj", paneId: "proj:director", hubPath: "/h" }, d);
    expect(ack.error).toContain("kickoff");
  });

  it("accepts when the director IS in the roster", () => {
    const d = deps();
    const ack = applyDirectorNew({ id: "1", projectKey: "proj", paneId: "proj:director", hubPath: "/h" }, d);
    expect(ack.created).toBe(true);
    expect(ack.error).toBeUndefined();
  });
});

// Does a DIRECTOR-ONLY plan actually launch a director?
//
// `bsc fleet director new` builds the smallest honest FleetPlan (a director, no streams) and hands it
// to `fleetStartProject`. In the field that produced no pane and no roster row, while the ack said it
// had worked — so this drives the REAL store action with that exact plan and asserts on what it
// returns, which is the evidence the ack should have been reading all along.
import { describe, it, expect, beforeEach } from "vitest";
import { useAppStore } from "@/store";
import { directorOnlyPlan } from "@/app/fleetDirectorBridge";

beforeEach(() => {
  useAppStore.setState({ tabs: [], activeTab: 0 } as never);
});

describe("a director-only plan", () => {
  it("returns a roster row naming the director's pane", () => {
    const rows = useAppStore
      .getState()
      .fleetStartProject("village-animal-hospital", directorOnlyPlan(), "village-animal-hospital", {
        hubPath: "/home/x/.base-studio-code/projects/village-animal-hospital",
      });
    // The row format is `<paneId>\tdirector\t-\t-\tdirector`.
    expect(rows.some((r) => r.startsWith("village-animal-hospital:director\t")), 
      `fleetStartProject returned ${rows.length} row(s): ${JSON.stringify(rows)}`).toBe(true);
  });

  it("creates a tab holding that pane", () => {
    useAppStore.getState().fleetStartProject("p", directorOnlyPlan(), "p", { hubPath: "/h" });
    const tabs = useAppStore.getState().tabs;
    expect(tabs.length, "a director-only launch must produce a tab").toBeGreaterThan(0);
  });
});

describe("the launch lands on the Console workspace", () => {
  // Console is a permanent workspace now (the #2372 opt-in was removed), so a launch simply asks for
  // it. The old guards here asserted a launch did not flip `showConsolePage`; that flag is gone.
  it("asks for the console workspace", () => {
    useAppStore.setState({ tabs: [], activeTab: 0 } as never);
    useAppStore.getState().fleetStartProject("p", directorOnlyPlan(), "p", { hubPath: "/h" });
    expect(useAppStore.getState().activeWorkspace).toBe("console");
  });
});
